const crypto=require('crypto');
const secret=String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET||'').trim();
const url=String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL||'').trim();
if(secret.length<32) throw new Error('release_command_secret_missing');
if(!/\/api\/v1\/automation\/control\/receipt$/.test(url)) throw new Error('release_control_url_invalid');
const id=String($execution.id||'');
if(!id) throw new Error('missing_execution_id');
const body=JSON.stringify({schema_version:1,action:'REFRESH_APPROVED_RELEASE_SOURCE',source:'cardcollectorcapital',execution_id:id.slice(0,120),occurred_at:new Date().toISOString()});
const timestamp=String(Math.floor(Date.now()/1000));
const signature='sha256='+crypto.createHmac('sha256',secret).update(timestamp+'.'+body,'utf8').digest('hex');
return [{json:{url:url.replace(/\/control\/receipt$/,'/commands/catalogue/refresh-release-source'),body,timestamp,signature}}];

const payload=$input.first().json||{};
if(Number(payload.statusCode)<200 || Number(payload.statusCode)>=300) throw new Error('release_source_http_'+payload.statusCode);
const r=payload.body||{};
if(r.accepted!==true || r.source!=='cardcollectorcapital' || typeof r.execution_id!=='string') throw new Error('release_source_receipt_invalid');
if(r.metadata_only!==true || r.artwork_published!==false || r.shopify_updated!==false || r.ownership_or_price_changed!==false) throw new Error('release_source_overreach');
if(!['CURRENT','PUBLISHED','ALREADY_RUNNING'].includes(r.status)) throw new Error('release_source_unavailable_'+String(r.status).slice(0,24));
if(r.status==='PUBLISHED' && (!Number.isInteger(r.generation)||r.generation<1||!Number.isInteger(r.record_count)||r.record_count<1)) throw new Error('published_release_generation_not_verified');
return [{json:{source:r.source,status:r.status,execution_id:r.execution_id,generation:r.generation,record_count:r.record_count,source_unchanged:r.source_unchanged}}];
